script:
const currentUser = frappe.session.user;
let activeCabRequest = null;

// Initialization
document.addEventListener("DOMContentLoaded", function () {
    getDriverAndTrip();
    setupEventListeners();
});

function getDriverAndTrip() {
    frappe.call({
        method: "frappe.client.get_list",
        args: {
            doctype: "Employee",
            fields: ["name"],
            filters: [["user_id", "=", currentUser]],
            limit: 1
        },
        callback: function(r) {
            if (r.message && r.message.length > 0) {
                const emp = r.message[0].name;
                frappe.call({
                    method: "frappe.client.get_list",
                    args: {
                        doctype: "Driver",
                        filters: [["employee", "=", emp]],
                        limit: 1
                    },
                    callback: function(d) {
                        if (d.message && d.message.length > 0) {
                            fetchActiveTrip(d.message[0].name);
                        }
                    }
                });
            }
        }
    });
}

function fetchActiveTrip(driver) {
    frappe.call({
        method: "frappe.client.get_list",
        args: {
            doctype: "Cab Request",
            fields: ["name", "start_odometer"],
            filters: [["driver_id", "=", driver], ["status", "=", "Assigned"]],
            limit: 1
        },
        callback: function(res) {
            if (res.message && res.message.length > 0) {
                activeCabRequest = res.message[0].name;
                document.getElementById("active-trip-id").innerHTML = `Trip ID: <strong>${activeCabRequest}</strong>`;
                document.getElementById("start-odometer").value = res.message[0].start_odometer || 0;
            }
        }
    });
}

function setupEventListeners() {
    const startInput = document.getElementById("start-odometer");
    const endInput = document.getElementById("end-odometer");
    const totalDist = document.getElementById("total-distance");

    const updateDist = () => {
        const s = parseFloat(startInput.value) || 0;
        const e = parseFloat(endInput.value) || 0;
        totalDist.innerText = e > s ? (e - s).toFixed(1) : "0";
    };

    startInput.addEventListener("input", updateDist);
    endInput.addEventListener("input", updateDist);

    document.getElementById("save-trip-btn").addEventListener("click", function() {
        submitTrip();
    });
}

function submitTrip() {
    const start = parseFloat(document.getElementById("start-odometer").value);
    const end = parseFloat(document.getElementById("end-odometer").value);
    const otp = document.getElementById("trip-otp").value;
    const verified = document.getElementById("verify-trip").checked;

    if (!activeCabRequest) return frappe.msgprint("No active trip.");
    if (end <= start) return frappe.msgprint("Check Odometer readings.");
    if (otp.length < 4) return frappe.msgprint("Enter Customer OTP.");
    if (!verified) return frappe.msgprint("Please check the verification box.");

    frappe.call({
        method: "frappe.client.set_value",
        args: {
            doctype: "Cab Request",
            name: activeCabRequest,
            fieldname: {
                end_odometer: end,
                total_distance: (end - start).toFixed(1),
                enter_otp: otp,
                verify: 1,
                status: "Completed"
            }
        },
        callback: function() {
            frappe.show_alert({message: "Trip Completed Successfully", indicator: "green"});
            location.reload();
        }
    });
}

