script:
var all_trips_data = [];

var refresh_dashboard = function() {
    frappe.call({
        method: "frappe.client.get_list",
        args: {
            doctype: "Cab Request",
            // Removed driver and vehicle fields from the fetch request
            fields: ["name", "creation", "employee_name", "status", "pickup_location", "drop_location"],
            filters: { "status": ["in", ["Assigned", "In Trip", "Completed", "Cancelled"]] },
            order_by: "creation desc",
            limit: 100
        },
        callback: function(r) {
            if (r.message) {
                all_trips_data = r.message;
                updateCounts();
                window.handleFilter();
            }
        }
    });
};

var updateCounts = function() {
    var counts = { Assigned: 0, "In Trip": 0, Completed: 0, Cancelled: 0 };
    for (var i = 0; i < all_trips_data.length; i++) {
        var status = all_trips_data[i].status;
        if (counts[status] !== undefined) counts[status]++;
    }

    if(root_element.querySelector('#count-assigned')) root_element.querySelector('#count-assigned').textContent = counts["Assigned"];
    if(root_element.querySelector('#count-intrip')) root_element.querySelector('#count-intrip').textContent = counts["In Trip"];
    if(root_element.querySelector('#count-completed')) root_element.querySelector('#count-completed').textContent = counts["Completed"];
    if(root_element.querySelector('#count-cancelled')) root_element.querySelector('#count-cancelled').textContent = counts["Cancelled"];
};

window.handleFilter = function() {
    var tbody = root_element.querySelector('#trip-table-body');
    var statusFilterHidden = root_element.querySelector('#status-filter-hidden');
    if (!tbody || !statusFilterHidden) return;

    var statusFilter = statusFilterHidden.value;
    tbody.innerHTML = "";

    for (var j = 0; j < all_trips_data.length; j++) {
        var row = all_trips_data[j];
        if (statusFilter === "All" || row.status === statusFilter) {
            var f_date = frappe.datetime.str_to_user(row.creation);
            var s_class = row.status.toLowerCase().replace(" ", "");

            // STRICT 4-COLUMN LAYOUT: Date, Employee, Route, Status
            var html_row = '<tr style="cursor: pointer;" onclick="frappe.set_route(\'Form\', \'Cab Request\', \'' + row.name + '\')">' +
                '<td style="font-size: 11px; white-space: nowrap;">' + f_date + '</td>' +
                '<td>' + (row.employee_name || "N/A") + '</td>' +
                '<td style="font-size: 11px;">' + row.pickup_location + '<br> &rarr; ' + row.drop_location + '</td>' +
                '<td><span class="badge badge-' + s_class + '">' + row.status + '</span></td>' +
            '</tr>';

            tbody.insertAdjacentHTML('beforeend', html_row);
        }
    }
};

// Collapse / expand the Live Trip Monitor table.
// No argument -> toggle. Pass true to force open, false to force close.
window.toggleTripMonitor = function(forceOpen) {
    var wrap = root_element.querySelector('#trip-table-wrap');
    var chev = root_element.querySelector('#tm-chevron');
    if (!wrap) return;
    var isOpen = wrap.style.display !== 'none';
    var open = (typeof forceOpen === 'boolean') ? forceOpen : !isOpen;
    wrap.style.display = open ? 'block' : 'none';
    if (chev) chev.style.transform = open ? 'rotate(90deg)' : 'rotate(0deg)';
};

window.filterByStatus = function(status) {
    var filter = root_element.querySelector('#status-filter-hidden');
    if (filter) {
        filter.value = status;
        window.handleFilter();
        window.toggleTripMonitor(true);   // reveal the monitor when a card / Show All is clicked
    }
};

refresh_dashboard();
setInterval(refresh_dashboard, 15000);

