  font-size:11px;font-weight:700;letter-spacing:.6px;}
.tms-mlm-meta{display:flex;align-items:center;gap:8px;flex-wrap:wrap;}
.tms-mlm-updated{font-size:12px;color:rgba(255,255,255,.8);}
.tms-mlm-btn{background:rgba(255,255,255,.14);border:1px solid rgba(255,255,255,.25);
  color:#fff;padding:6px 12px;border-radius:8px;font-size:13px;cursor:pointer;
  transition:background .15s ease;}
.tms-mlm-btn:hover{background:rgba(255,255,255,.25);}
.tms-mlm-btn-primary{background:#fff;color:var(--tms-green-d);border-color:#fff;font-weight:600;}
.tms-mlm-btn-primary:hover{background:#f1f5f9;}

.tms-mlm-body{display:grid;grid-template-columns:1fr 320px;gap:0;}
.tms-mlm-map-wrap{position:relative;background:#eef2f6;}
.tms-mlm-map{width:100%;height:60vh;min-height:360px;}
.tms-mlm-overlay{position:absolute;inset:0;display:flex;align-items:center;justify-content:center;
  background:rgba(255,255,255,.7);pointer-events:none;transition:opacity .25s;}
.tms-mlm-overlay.tms-hidden{opacity:0;visibility:hidden;}
.tms-mlm-overlay-msg{padding:8px 14px;background:#fff;border-radius:8px;
  box-shadow:0 4px 12px rgba(0,0,0,.08);font-size:13px;color:var(--tms-muted);}

.tms-mlm-side{border-left:1px solid var(--tms-line);display:flex;flex-direction:column;
  max-height:calc(60vh + 0px);min-height:360px;background:#fafbfc;}
.tms-mlm-side-head{display:flex;align-items:center;justify-content:space-between;
  padding:12px 14px;border-bottom:1px solid var(--tms-line);background:#fff;}
.tms-mlm-side-title{font-weight:600;font-size:13px;letter-spacing:.4px;
  text-transform:uppercase;color:var(--tms-muted);}
.tms-mlm-side-count{background:var(--tms-green);color:#fff;border-radius:999px;
  padding:1px 9px;font-size:12px;font-weight:700;}
.tms-mlm-side-list{overflow-y:auto;padding:8px;display:flex;flex-direction:column;gap:6px;flex:1;}
.tms-mlm-empty{color:var(--tms-muted);font-size:13px;padding:24px 12px;text-align:center;}

.tms-mlm-card{border:1px solid var(--tms-line);border-radius:10px;padding:10px 12px;
  background:#fff;cursor:pointer;transition:border-color .15s,box-shadow .15s;}
.tms-mlm-card:hover{border-color:var(--tms-green);box-shadow:0 4px 10px rgba(25,135,84,.08);}
.tms-mlm-card.tms-active{border-color:var(--tms-green);box-shadow:0 4px 10px rgba(25,135,84,.15);}
.tms-mlm-card-top{display:flex;align-items:center;justify-content:space-between;gap:8px;
  margin-bottom:6px;}
.tms-mlm-card-vehicle{font-weight:700;font-size:13px;color:var(--tms-fg);}
.tms-mlm-card-pill{font-size:10px;font-weight:700;padding:2px 8px;border-radius:999px;
  text-transform:uppercase;letter-spacing:.4px;}
.tms-mlm-card-pill.fresh{background:#d1fae5;color:#065f46;}
.tms-mlm-card-pill.stale{background:#fee2e2;color:#991b1b;}
.tms-mlm-card-row{font-size:12px;color:var(--tms-muted);display:flex;
  align-items:center;justify-content:space-between;gap:6px;}
.tms-mlm-card-row b{color:var(--tms-fg);font-weight:600;}

@media (max-width:880px){
  .tms-mlm-body{grid-template-columns:1fr;}
  .tms-mlm-map{height:50vh;min-height:320px;}
  .tms-mlm-side{border-left:0;border-top:1px solid var(--tms-line);max-height:none;}
  .tms-mlm-side-list{max-height:40vh;}
}
@media (max-width:480px){
  .tms-mlm-header{padding:10px 12px;}
  .tms-mlm-meta{width:100%;justify-content:flex-end;}
  .tms-mlm-updated{flex:1;}
  .tms-mlm-map{height:48vh;min-height:300px;}
}
